input.command:
mkdir -p src/inngest src/app/api/inngest && cat > src/inngest/client.ts <<'EOF'
import { Inngest } from "inngest";

// Reads INNGEST_EVENT_KEY / INNGEST_SIGNING_KEY from the environment.
export const inngest = new Inngest({ id: "notely" });
EOF
cat > src/inngest/functions.ts <<'EOF'
import { inngest } from "./client";

export const USER_CREATED_EVENT = "notely/user.created";
export const REMINDER_DELAY_MS = 10 * 60 * 1000;

export type UserCreatedData = { userId: string; email: string; name: string };

// Runs once per created user. The event is sent with a future `ts`, so Inngest
// holds it until then. A thrown error is retried with backoff (up to `retries`).
export const userReminder = inngest.createFunction(
  {
    id: "user-reminder",
    retries: 4,
    triggers: [{ event: USER_CREATED_EVENT }],
  },
  async ({ event, attempt, logger }) => {
    const { userId, email, name } = event.data as UserCreatedData;
    logger.info(
      `Reminder: say hello to ${name} <${email}> (user ${userId}), attempt ${attempt + 1}`,
    );
    return { userId, reminded: true };
  },
);

export const functions = [userReminder];
EOF
cat > src/app/api/inngest/route.ts <<'EOF'
import { serve } from "inngest/next";
import { inngest } from "@/inngest/client";
import { functions } from "@/inngest/functions";

export const { GET, POST, PUT } = serve({ client: inngest, functions });
EOF
cat >> src/lib/users.ts <<'EOF'

export async function createUser(input: { email: string; name: string }): Promise<User> {
  const user: User = {
    id: String(users.length + 1),
    email: input.email,
    name: input.name,
    createdAt: new Date().toISOString(),
  };
  users.push(user);

  // Schedule the reminder job. If scheduling fails, the user is still created.
  try {
    await inngest.send({
      name: USER_CREATED_EVENT,
      data: { userId: user.id, email: user.email, name: user.name } satisfies UserCreatedData,
      ts: Date.now() + REMINDER_DELAY_MS,
    });
  } catch (err) {
    console.error(`Failed to schedule reminder for user ${user.id}`, err);
  }

  return user;
}
EOF
sed -i '' '1i\
import { inngest } from "@/inngest/client";\
import { USER_CREATED_EVENT, REMINDER_DELAY_MS, type UserCreatedData } from "@/inngest/functions";\
\
' src/lib/users.ts
cat > .env.example <<'EOF'
